import time

# Test if try/except has overhead when no exception
def f1(d):
    try:
        return d.get(1)
    except TypeError:
        return None

def f2(d):
    return d.get(1)

d = {1: 'a', 2: 'b'}
n = 1000000

t = time.perf_counter()
for _ in range(n):
    f1(d)
print('with try:', time.perf_counter() - t)

t = time.perf_counter()
for _ in range(n):
    f2(d)
print('without try:', time.perf_counter() - t)
"

