cd /workspace/pydantic__pydantic && source .venv/bin/activate && python -c "
import time
from pydantic_core import PydanticCustomError

err = PydanticCustomError('enum', 'Input should be {expected}', {'expected': 'foo, bar'})

# Test raising preconstructed vs creating new each time
def f1():
    raise PydanticCustomError('enum', 'Input should be {expected}', {'expected': 'foo, bar'})

def f2():
    raise err

n = 100000
t = time.perf_counter()
for _ in range(n):
    try:
        f1()
    except PydanticCustomError:
        pass
print('new each time:', time.perf_counter() - t)

t = time.perf_counter()
for _ in range(n):
    try:
        f2()
    except PydanticCustomError:
        pass
print('preconstructed:', time.perf_counter() - t)
"

